-- ============================================================
-- V1: Create article_meta table
-- ============================================================

CREATE TABLE IF NOT EXISTS article_meta (
    id                   BIGSERIAL     PRIMARY KEY,
    document_id          VARCHAR(100)  NOT NULL UNIQUE,
    title                VARCHAR(512),
    authors              VARCHAR(1024),
    published_year       INTEGER,
    publication_type     VARCHAR(100),
    journal_or_conference VARCHAR(512),
    summary              TEXT,
    abstract_text        TEXT,
    document_link        VARCHAR(2048),
    local_file_path      VARCHAR(2048),
    created_at           TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW() NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_article_document_id ON article_meta(document_id);
CREATE INDEX IF NOT EXISTS idx_article_published_year ON article_meta(published_year);



